<script>
// --- Simulated page-detail fetch (prototype only) --------------------------
// A prototype simulates external behaviour. Real fetching would read the live
// page; here we return believable details for a few known links, and derive a
// sensible fallback for anything else.
const CATALOG = {
  "https://martinfowler.com/articles/practical-test-pyramid.html": {
    title: "The Practical Test Pyramid",
    description: "A guide to the test pyramid: how to structure automated tests across unit, service and UI layers for fast, reliable feedback.",
    host: "martinfowler.com",
    favicon: "https://www.google.com/s2/favicons?domain=martinfowler.com&sz=64",
    image: "https://martinfowler.com/articles/practical-test-pyramid/test-pyramid.png"
  },
  "https://en.wikipedia.org/wiki/bookmark_(digital)": {
    title: "Bookmark (digital) — Wikipedia",
    description: "A bookmark is a Uniform Resource Identifier (URI) that is stored for later retrieval in any of various storage formats.",
    host: "en.wikipedia.org",
    favicon: "https://www.google.com/s2/favicons?domain=en.wikipedia.org&sz=64",
    image: ""
  }
};

function fakeFetch(url) {
  const key = url.toLowerCase().replace(/\/+$/,'');
  return new Promise(resolve => {
    setTimeout(() => {
      if (CATALOG[key]) return resolve(CATALOG[key]);
      let host = "";
      try { host = new URL(url).hostname.replace(/^www\./,''); } catch(e) { host = url; }
      const slug = (function(){
        try {
          const p = new URL(url).pathname.split('/').filter(Boolean).pop() || "";
          return decodeURIComponent(p).replace(/[-_]+/g,' ').replace(/\.\w+$/,'');
        } catch(e) { return ""; }
      })();
      resolve({
        title: slug ? (slug.charAt(0).toUpperCase()+slug.slice(1)) : host,
        description: "Saved from " + host + ".",
        host: host,
        favicon: "https://www.google.com/s2/favicons?domain=" + host + "&sz=64",
        image: ""
      });
    }, 900);
  });
}

// --- State -----------------------------------------------------------------
const bookmarks = [];
const listEl = document.getElementById('list');
const emptyEl = document.getElementById('empty');

function normalizeUrl(raw) {
  let u = raw.trim();
  if (!u) return "";
  if (!/^https?:\/\//i.test(u)) u = "https://" + u;
  return u;
}

function render() {
  emptyEl.style.display = bookmarks.length ? "none" : "block";
  listEl.innerHTML = "";
  bookmarks.forEach(b => {
    const card = document.createElement('div');
    card.className = "card" + (b.pending ? " pending" : "");
    if (b.pending) {
      card.innerHTML = `
        <div class="thumb"></div>
        <div class="body">
          <div class="fetching"><span class="spin"></span>Fetching page details…</div>
          <div class="skeleton t" style="margin-top:10px"></div>
          <div class="skeleton d"></div>
          <div class="skeleton d2"></div>
        </div>`;
    } else {
      card.innerHTML = `
        <div class="thumb" style="${b.image ? `background-image:url('${b.image}')` : ''}"></div>
        <div class="body">
          <div class="title-row">
            <img class="favicon" src="${b.favicon}" alt="" onerror="this.style.visibility='hidden'"/>
            <h3 class="title"><a href="${b.url}" target="_blank" rel="noopener">${escapeHtml(b.title)}</a></h3>
          </div>
          <p class="desc">${escapeHtml(b.description)}</p>
          <p class="host">${escapeHtml(b.host)}</p>
        </div>`;
    }
    listEl.appendChild(card);
  });
}

function escapeHtml(s){ return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

document.getElementById('saver').addEventListener('submit', async (e) => {
  e.preventDefault();
  const input = document.getElementById('url');
  const btn = document.getElementById('saveBtn');
  const url = normalizeUrl(input.value);
  if (!url) return;
  const entry = { url, pending: true };
  bookmarks.unshift(entry);
  input.value = "";
  btn.disabled = true;
  render();
  const details = await fakeFetch(url);
  Object.assign(entry, details, { pending: false });
  btn.disabled = false;
  render();
});

render();
window.addEventListener('load', () => document.body.setAttribute('data-harness-ready','true'));
</script>
